// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // Ensure the caller is not the current owner, so the property is meaningful.
        vm.assume(caller != c.owner());
        // Ensure the new owner is not the same as the current owner, so a change is observable.
        vm.assume(newOwner != c.owner());

        // Record the owner before the call.
        address ownerBefore = c.owner();

        // Attempt to change the owner from a non-owner address.
        vm.prank(caller);
        bool success = c.setOwner(newOwner);

        // After a call from a non-owner, the owner must remain unchanged.
        // The correct contract reverts here, so the owner stays the same.
        // The buggy contract succeeds and changes the owner, violating this assertion.
        assertTrue(c.owner() == ownerBefore);
    }
}
